    org_2faWarning:      { de: 'Nur aktivieren, wenn <em>alle</em> Benutzerkonten bereits 2FA eingerichtet haben. Andernfalls werden betroffene Konten sofort ausgesperrt.', en: 'Only enable if <em>all</em> user accounts already have 2FA set up. Otherwise affected accounts will be locked out immediately.', fr: 'Activez uniquement si <em>tous</em> les comptes utilisateurs ont déjà configuré la 2FA. Sinon, les comptes concernés seront immédiatement bloqués.', nl: 'Alleen inschakelen als <em>alle</em> gebruikersaccounts al 2FA hebben ingesteld. Anders worden getroffen accounts direct buitengesloten.' , hu: 'Csak akkor engedélyezze, ha <em>minden</em> felhasználói fiókhoz már be van állítva a 2FA. Ellenkező esetben az érintett fiókok azonnal kizárásra kerülnek.' },
    org_saveSecurity:    { de: 'Sicherheitseinstellungen speichern', en: 'Save security settings', fr: 'Enregistrer les paramètres de sécurité', nl: 'Beveiligingsinstellingen opslaan' , hu: 'Biztonsági beállítások mentése' },
    org_emailNotifications:{ de: 'E-Mail-Benachrichtigungen', en: 'E-Mail Notifications',     fr: 'Notifications par e-mail',  nl: 'E-mailmeldingen' , hu: 'E-mail értesítések' },
    org_smtpEnvNotice:   { de: 'SMTP-Zugangsdaten werden in der Datei <code>.env</code> konfiguriert (<code>SMTP_HOST</code>, <code>SMTP_USER</code> usw.). Hier werden nur Benachrichtigungstypen gesteuert.', en: 'SMTP credentials are configured in the <code>.env</code> file (<code>SMTP_HOST</code>, <code>SMTP_USER</code> etc.). Only notification types are controlled here.', fr: 'Les identifiants SMTP sont configurés dans le fichier <code>.env</code> (<code>SMTP_HOST</code>, <code>SMTP_USER</code>, etc.). Seuls les types de notification sont gérés ici.', nl: 'SMTP-gegevens worden geconfigureerd in het bestand <code>.env</code> (<code>SMTP_HOST</code>, <code>SMTP_USER</code>, enz.). Hier worden alleen meldingstypen beheerd.' , hu: 'Az SMTP hitelesítési adatok a <code>.env</code> fájlban vannak konfigurálva (<code>SMTP_HOST</code>, <code>SMTP_USER</code> stb.). Itt csak az értesítési típusok szabályozhatók.' },
    org_enableDigest:    { de: 'Tägliche Digest-E-Mails aktivieren', en: 'Enable daily digest e-mails', fr: 'Activer les e-mails de synthèse quotidiens', nl: 'Dagelijkse digest-e-mails inschakelen' , hu: 'Napi összefoglaló e-mailek engedélyezése' },
    org_digestDesc:      { de: 'Sendet einmal täglich eine Zusammenfassung an CISO, GDPO und Admin-E-Mail.', en: 'Sends a daily summary to CISO, GDPO and admin e-mail once per day.', fr: 'Envoie une synthèse quotidienne au RSSI, au DPD et à l’e-mail admin une fois par jour.', nl: 'Verstuurt eenmaal per dag een samenvatting naar CISO, FG en admin-e-mail.' , hu: 'Naponta egyszer összefoglalót küld a CISO, a GDPO és az adminisztrátori e-mail-re.' },
    org_adminEmail:      { de: 'Admin-E-Mail',              en: 'Admin E-Mail',               fr: 'E-mail admin',              nl: 'Admin-e-mail' , hu: 'Adminisztrátori e-mail' },
    org_emailHighRisks:  { de: 'Hohe/kritische Risiken',    en: 'High/critical risks',        fr: 'Risques élevés/critiques',  nl: 'Hoge/kritieke risico’s' , hu: 'Magas/kritikus kockázatok' },
    org_emailBcmDue:     { de: 'BCM-Tests fällig (≤ 14 Tage)', en: 'BCM tests due (≤ 14 days)', fr: 'Tests PCA dus (≤ 14 jours)', nl: 'BCM-tests vervallen (≤ 14 dagen)' , hu: 'Esedékes BCM-tesztek (≤ 14 nap)' },
    org_emailSupplierAudits:{ de: 'Lieferantenaudits fällig (≤ 14 Tage)', en: 'Supplier audits due (≤ 14 days)', fr: 'Audits fournisseurs dus (≤ 14 jours)', nl: 'Leveranciersaudits vervallen (≤ 14 dagen)' , hu: 'Esedékes szállítói auditok (≤ 14 nap)' },
    org_emailDsar:       { de: 'DSAR-Fristen (≤ 3 Tage)',   en: 'DSAR deadlines (≤ 3 days)',  fr: 'Échéances DSAR (≤ 3 jours)', nl: 'DSAR-deadlines (≤ 3 dagen)' , hu: 'DSAR határidők (≤ 3 nap)' },
    org_emailGdprIncidents:{ de: 'GDPR-Vorfälle > 48h offen', en: 'GDPR incidents > 48h open', fr: 'Incidents RGPD ouverts > 48h', nl: 'AVG-incidenten > 48u open' , hu: 'GDPR-incidensek > 48 óra nyitva' },
    org_emailDeletionLog:{ de: 'Löschprotokoll Art. 17 GDPR', en: 'Deletion log Art. 17 GDPR', fr: 'Journal de suppression art. 17 RGPD', nl: 'Verwijderlog art. 17 AVG' , hu: 'Törlési napló (GDPR 17. cikk)' },
