    org_toGdpo:          { de: '→ GDPO-E-Mail',             en: '→ GDPO e-mail',              fr: '→ e-mail DPD',              nl: '→ FG-e-mail' , hu: '→ GDPO e-mail' },
    org_toAdmin:         { de: '→ Admin-E-Mail',            en: '→ Admin e-mail',             fr: '→ e-mail admin',            nl: '→ Admin-e-mail' , hu: '→ Adminisztrátori e-mail' },
    org_saveEmail:       { de: 'E-Mail-Einstellungen speichern', en: 'Save e-mail settings',  fr: 'Enregistrer les paramètres e-mail', nl: 'E-mailinstellingen opslaan' , hu: 'E-mail beállítások mentése' },
    org_smtpConfig:      { de: 'SMTP-Konfiguration',        en: 'SMTP Configuration',         fr: 'Configuration SMTP',        nl: 'SMTP-configuratie' , hu: 'SMTP-konfiguráció' },
    org_securityNotice:  { de: 'Sicherheitshinweis',        en: 'Security notice',            fr: 'Avis de sécurité',          nl: 'Beveiligingsmelding' , hu: 'Biztonsági megjegyzés' },
    org_smtpSecurityNotice:{ de: 'Das SMTP-Passwort wird in <code>org-settings.json</code> gespeichert (Klartext). Für höhere Sicherheit verwenden Sie Umgebungsvariablen (<code>SMTP_HOST</code> usw.) in <code>.env</code> — diese haben immer Vorrang.', en: 'The SMTP password is stored in <code>org-settings.json</code> (plaintext). For higher security, use environment variables (<code>SMTP_HOST</code> etc.) in <code>.env</code> — these always take precedence.', fr: 'Le mot de passe SMTP est stocké dans <code>org-settings.json</code> (texte clair). Pour plus de sécurité, utilisez des variables d’environnement (<code>SMTP_HOST</code>, etc.) dans <code>.env</code> — elles sont toujours prioritaires.', nl: 'Het SMTP-wachtwoord wordt opgeslagen in <code>org-settings.json</code> (platte tekst). Gebruik voor meer veiligheid omgevingsvariabelen (<code>SMTP_HOST</code>, enz.) in <code>.env</code> — die hebben altijd voorrang.' , hu: 'Az SMTP-jelszó az <code>org-settings.json</code> fájlban tárolódik (egyszerű szövegként). Magasabb biztonság érdekében használjon környezeti változókat (<code>SMTP_HOST</code> stb.) a <code>.env</code> fájlban - ezek mindig elsőbbséget élveznek.' },
    org_smtpEnvOverride: { de: 'SMTP ist über <code>.env</code>-Variablen konfiguriert — UI-Einstellungen werden ignoriert.', en: 'SMTP is configured via <code>.env</code> variables — UI settings are ignored.', fr: 'SMTP est configuré via des variables <code>.env</code> — les paramètres de l’interface sont ignorés.', nl: 'SMTP is geconfigureerd via <code>.env</code>-variabelen — UI-instellingen worden genegeerd.' , hu: 'Az SMTP a <code>.env</code> változók segítségével van konfigurálva - a felhasználói felület beállításai figyelmen kívül lesznek hagyva.' },
