    org_testMailDesc:    { de: 'Die Testmail wird an die CISO-E-Mail ({email}) gesendet. Bitte zuerst unter Verantwortlichkeiten eine CISO-E-Mail eintragen.', en: 'Test mail will be sent to the CISO e-mail ({email}). Please enter a CISO e-mail under Responsibilities first.', fr: 'L’e-mail de test sera envoyé à l’e-mail du RSSI ({email}). Veuillez d’abord saisir un e-mail RSSI dans Responsabilités.', nl: 'De testmail wordt verzonden naar de CISO-e-mail ({email}). Voer eerst een CISO-e-mail in onder Verantwoordelijkheden.' , hu: 'A tesztelő e-mail a CISO e-mail-jére ({email}) lesz elküldve. Kérjük, először adja meg a CISO e-mail-jét a Felelősségek alatt.' },
    org_menuOrder:       { de: 'Menüreihenfolge',           en: 'Menu Order',                 fr: 'Ordre du menu',             nl: 'Menuvolgorde' , hu: 'Menü sorrendje' },
    org_menuOrderDesc:   { de: 'Einträge mit <i class="ph ph-dots-six-vertical"></i> ziehen oder ↑/↓ verwenden, um die Sidebar-Reihenfolge anzupassen. Dashboard, Admin und Einstellungen werden immer angezeigt.', en: 'Drag entries with <i class="ph ph-dots-six-vertical"></i> or use ↑/↓ to adjust the sidebar order. Dashboard, Admin and Settings are always shown.', fr: 'Faites glisser les entrées avec <i class="ph ph-dots-six-vertical"></i> ou utilisez ↑/↓ pour ajuster l’ordre de la barre latérale. Tableau de bord, Admin et Paramètres sont toujours affichés.', nl: 'Sleep items met <i class="ph ph-dots-six-vertical"></i> of gebruik ↑/↓ om de zijbalkvolgorde aan te passen. Dashboard, Beheer en Instellingen worden altijd getoond.' , hu: 'Húzza az elemeket a <i class="ph ph-dots-six-vertical"></i> ikonnal, vagy használja a ↑/↓ gombokat az oldalsáv sorrendjének módosításához. Az Irányítópult, az Admin és a Beállítások mindig látható.' },
    org_saveOrder:       { de: 'Reihenfolge speichern',     en: 'Save order',                 fr: 'Enregistrer l’ordre',       nl: 'Volgorde opslaan' , hu: 'Sorrend mentése' },
    org_units:           { de: 'Organisationseinheiten',    en: 'Organisational Units',       fr: 'Unités organisationnelles', nl: 'Organisatie-eenheden' , hu: 'Szervezeti egységek' },
    org_newUnit:         { de: 'Neue Einheit',              en: 'New Unit',                   fr: 'Nouvelle unité',            nl: 'Nieuwe eenheid' , hu: 'Új egység' },
    org_unitsDesc:       { de: 'Definiert die IT-Organisationsstruktur (CIO → GroupIT / GroupApp → Local IT). Wird für Verantwortungszuweisungen in allen Modulen verwendet (Risiken, Assets, Lieferanten, BCM, Ziele, Findings).', en: 'Defines the IT org structure (CIO → GroupIT / GroupApp → Local IT). Used for ownership assignment across all modules (Risks, Assets, Suppliers, BCM, Goals, Findings).', fr: 'Définit la structure IT (CIO → GroupIT / GroupApp → Local IT). Utilisé pour l’attribution des responsabilités dans tous les modules (risques, actifs, fournisseurs, PCA, objectifs, constats).', nl: 'Definieert de IT-organisatiestructuur (CIO → GroupIT / GroupApp → Local IT). Gebruikt voor eigenaarschapstoewijzing in alle modules (risico’s, assets, leveranciers, BCM, doelen, bevindingen).' , hu: 'Az IT szervezeti struktúrát határozza meg (CIO → GroupIT / GroupApp → Helyi IT). Az összes modul (Kockázatok, Eszközök, Szállítók, BCM, Célok, Megállapítások) felelősség-hozzárendeléséhez használatos.' },
