    org_itUnit:          { de: 'IT-Organisationseinheit',    en: 'IT Organisational Unit',     fr: 'Unité organisationnelle IT', nl: 'IT-organisatie-eenheid' , hu: 'IT szervezeti egység' },
    org_parentUnit:      { de: 'Übergeordnete Einheit',      en: 'Parent Unit',                fr: 'Unité parente',             nl: 'Bovenliggende eenheid' , hu: 'Szülő egység' },
