    modmeta_soa: { de: 'Verwaltung aller Compliance-Controls (ISO 27001, BSI, NIS2, EUCS, EUAI, ISO 9001, CRA). Framework-Tabs, Inline-Bearbeitung, Cross-Mapping.', en: 'Management of all compliance controls (ISO 27001, BSI, NIS2, EUCS, EUAI, ISO 9001, CRA). Framework tabs, inline editing, cross-mapping.', fr: 'Gestion de tous les contrôles de conformité (ISO 27001, BSI, NIS2, EUCS, EUAI, ISO 9001, CRA). Onglets par référentiel, édition en ligne, correspondances croisées.', nl: 'Beheer van alle compliance-controls (ISO 27001, BSI, NIS2, EUCS, EUAI, ISO 9001, CRA). Frameworktabs, inline bewerken, cross-mapping.', hu: 'Az összes megfelelőségi kontroll kezelése (ISO 27001, BSI, NIS2, EUCS, EUAI, ISO 9001, CRA). Keretrendszer-fülek, soron belüli szerkesztés, keresztleképezés.' },
    modmeta_guidance: { de: 'Interner Dokumentationshub: Systemhandbuch, Rollen, Richtlinienprozesse, SoA-Leitfäden. Markdown-Editor + PDF/DOCX-Upload.', en: 'Internal documentation hub: system manual, roles, policy processes, SoA guides. Markdown editor + PDF/DOCX upload.', fr: 'Centre de documentation interne : manuel système, rôles, processus de politiques, guides SoA. Éditeur Markdown + téléversement PDF/DOCX.', nl: 'Interne documentatiehub: systeemhandleiding, rollen, beleidsprocessen, SoA-handleidingen. Markdown-editor + PDF/DOCX-upload.', hu: 'Belső dokumentációs központ: rendszerkézikönyv, szerepkörök, szabályzati folyamatok, SoA-útmutatók. Markdown-szerkesztő + PDF/DOCX-feltöltés.' },
    modmeta_goals: { de: 'SMART-Sicherheitsziele mit KPI-Verfolgung, Fortschrittsbalken, Prioritäten und Kalenderanbindung.', en: 'SMART security goals with KPI tracking, progress bars, priorities and calendar integration.', fr: 'Objectifs de sécurité SMART avec suivi des KPI, barres de progression, priorités et intégration au calendrier.', nl: 'SMART-beveiligingsdoelen met KPI-opvolging, voortgangsbalken, prioriteiten en agenda-integratie.', hu: 'SMART biztonsági célok KPI-követéssel, folyamatjelzőkkel, prioritásokkal és naptár-integrációval.' },
    modmeta_risk: { de: 'Risikoregister mit Heatmap, Behandlungsplänen, Risikomatrix und Kalender. Rollen: contentowner und auditor.', en: 'Risk register with heatmap, treatment plans, risk matrix and calendar. Roles: contentowner and auditor.', fr: 'Registre des risques avec carte thermique, plans de traitement, matrice des risques et calendrier. Rôles : contentowner et auditor.', nl: 'Risicoregister met heatmap, behandelplannen, risicomatrix en agenda. Rollen: contentowner en auditor.', hu: 'Kockázati nyilvántartás hőtérképpel, kezelési tervekkel, kockázati mátrixszal és naptárral. Szerepkörök: contentowner és auditor.' },
    modmeta_legal: { de: 'Verwaltung von Verträgen, NDAs und Datenschutzerklärungen mit Laufzeitverfolgung und Kalenderanbindung.', en: 'Management of contracts, NDAs and privacy policies with term tracking and calendar integration.', fr: 'Gestion des contrats, NDA et politiques de confidentialité avec suivi des échéances et intégration au calendrier.', nl: 'Beheer van contracten, NDA\'s en privacybeleid met looptijdbewaking en agenda-integratie.', hu: 'Szerződések, NDA-k és adatvédelmi szabályzatok kezelése a határidők követésével és naptár-integrációval.' },
    modmeta_incident: { de: 'Posteingang für öffentlich gemeldete Sicherheitsvorfälle (Meldung ohne Login). CISO-Bearbeitung, Referenznummern, Zuweisung.', en: 'Inbox for publicly reported security incidents (no login required for reporting). CISO handling, reference numbers, assignment.', fr: 'Boîte de réception des incidents de sécurité signalés publiquement (signalement sans connexion). Traitement par le CISO, numéros de référence, affectation.', nl: 'Inbox voor openbaar gemelde beveiligingsincidenten (melden zonder inloggen). Afhandeling door de CISO, referentienummers, toewijzing.', hu: 'Nyilvánosan bejelentett biztonsági incidensek postaládája (bejelentés bejelentkezés nélkül). CISO általi kezelés, hivatkozási számok, hozzárendelés.' },
    modmeta_gdpr: { de: 'Vollständiges DSGVO-Modul: VVT (Art. 30), AV-Verträge (Art. 28), DSFA (Art. 35), Datenpannen (Art. 33/34), Betroffenenanfragen (Art. 15–22), TOMs (Art. 32), DSB (Art. 37), Löschprotokoll (Art. 17).', en: 'Full GDPR module: RoPA (Art. 30), DPA (Art. 28), DPIA (Art. 35), data breaches (Art. 33/34), DSAR (Art. 15–22), TOMs (Art. 32), DPO (Art. 37), deletion log (Art. 17).', fr: 'Module RGPD complet : registre des traitements (art. 30), contrats de sous-traitance (art. 28), AIPD (art. 35), violations de données (art. 33/34), demandes des personnes concernées (art. 15–22), mesures techniques et organisationnelles (art. 32), DPO (art. 37), journal des suppressions (art. 17).', nl: 'Volledige AVG-module: verwerkingsregister (art. 30), verwerkersovereenkomsten (art. 28), DPIA (art. 35), datalekken (art. 33/34), verzoeken van betrokkenen (art. 15–22), TOM\'s (art. 32), FG (art. 37), verwijderlogboek (art. 17).', hu: 'Teljes GDPR-modul: adatkezelési nyilvántartás (30. cikk), adatfeldolgozói szerződések (28. cikk), DPIA (35. cikk), adatvédelmi incidensek (33/34. cikk), érintetti kérelmek (15–22. cikk), TOM-ok (32. cikk), DPO (37. cikk), törlési napló (17. cikk).' },
    modmeta_training: { de: 'Schulungsplanung mit Statusverfolgung, Fälligkeiten, Teilnehmergruppen und Kalenderanbindung.', en: 'Training planning with status tracking, due dates, assignee groups and calendar integration.', fr: 'Planification des formations avec suivi du statut, échéances, groupes de participants et intégration au calendrier.', nl: 'Trainingsplanning met statusopvolging, deadlines, deelnemersgroepen en agenda-integratie.', hu: 'Képzéstervezés állapotkövetéssel, határidőkkel, résztvevői csoportokkal és naptár-integrációval.' },
    modmeta_reports: { de: '7 Berichtstypen: Compliance, Framework, Gap-Analyse, Dokumente, Reviews, Compliance-Matrix, Audit-Trail. CSV-Export.', en: '7 report types: Compliance, Framework, Gap Analysis, Documents, Reviews, Compliance Matrix, Audit Trail. CSV export.', fr: '7 types de rapports : conformité, référentiel, analyse des écarts, documents, revues, matrice de conformité, piste d\'audit. Export CSV.', nl: '7 rapporttypen: compliance, framework, gap-analyse, documenten, beoordelingen, compliancematrix, audittrail. CSV-export.', hu: '7 jelentéstípus: megfelelőség, keretrendszer, hiányelemzés, dokumentumok, felülvizsgálatok, megfelelőségi mátrix, auditnapló. CSV-export.' },
